// Sheet columns: URL, USERNAME, PASSWORD_REF (or PASSWORD), SUBMIT, TAB,
// BUTTON, and optional ENABLED. One row per account. Every row goes out in a
// single /run call as a jobs array, so the Wait node parks once for the whole
// batch, not once per row.
//
// Explicit goals instead of a bare task: the sheet already says which button
// to press, so the planner has nothing left to guess (and costs no LLM call).
//
// PASSWORD_REF holds the NAME of an env key on the agent box (PA_PASSWORD),
// not the password itself. It leaves here as ${PA_PASSWORD} and the agent
// resolves it from its own .env, so the secret never reaches the sheet, Google
// or n8n. A literal PASSWORD column still works, but then anyone with the
// sheet or an execution log has that password.
//
// session stays false on purpose. The agent keys its saved session by host
// (src/memory/sessions/<host>.json), and every row here is the same host with
// a different account — reusing it would log the next row in as the previous
// user. Each row logs in for itself.

// Header matching ignores case, spaces and underscores, so "Password Ref",
// "password_ref" and "PASSWORDREF" are all the same column.
const squash = text => text.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');

const pick = (row, key) => {
    const header = Object.keys(row).find(name => squash(name) === squash(key));

    return header ? String(row[header] ?? '').trim() : '';
};

const rows = $input.all().map(item => item.json)
    .map(row => ({
        url: pick(row, 'URL'),
        username: pick(row, 'USERNAME'),
        password: pick(row, 'PASSWORD'),
        passwordRef: pick(row, 'PASSWORD_REF').replace(/^\$\{|\}$/g, ''),
        enabled: pick(row, 'ENABLED'),
        submit: pick(row, 'SUBMIT') || 'Log in',
        tab: pick(row, 'TAB'),
        button: pick(row, 'BUTTON')
    }))
    .filter(row => row.url && row.username)
    .filter(row => !/^(no|false|0|off)$/i.test(row.enabled));

// Without this the row still runs a browser and only fails at the login form,
// minutes later, looking like a broken selector rather than a blank cell.
const unset = rows.filter(row => !row.password && !row.passwordRef);

if (unset.length > 0) {
    throw new Error(`No password for: ${unset.map(row => row.username).join(', ')} — fill PASSWORD_REF (the name of an env key on the agent box) or PASSWORD.`);
}

if (rows.length === 0) {
    throw new Error('No usable rows: each needs URL and USERNAME, with ENABLED not set to no/false/0.');
}

const jobs = rows.map(row => ({
    name: row.username,
    url: row.url,
    task: `Log in as ${row.username} and click ${row.button || row.tab}`,
    session: false,
    goals: [
        { goal: `Enter the username and password then click ${row.submit}`, done: 'Dashboard is visible' },
        ...(row.tab ? [{ goal: `Open the ${row.tab} tab`, done: `The ${row.tab} page is visible` }] : []),
        ...(row.button ? [{ goal: `Click ${row.button}`, done: 'The date on the button moved forward' }] : [])
    ],
    variables: {
        USERNAME: row.username,
        PASSWORD: row.passwordRef ? '${' + row.passwordRef + '}' : row.password
    }
}));

return [{ json: { jobs, callbackUrl: $execution.resumeUrl } }];
